sys_script_include.script:
var DoppelUIHelper = Class.create();
DoppelUIHelper.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    getDoppelLink: function () {
        var obsId = String(this.getParameter('sysparm_obs_id') || '');
        var obs = new GlideRecord('sn_ti_observable');
        if (!obsId || !obs.get(obsId) || !obs.canRead()) return '';
        return new DoppelIOCImport().getLatestDoppelLink(obsId);
    },

    // Test Connectivity button on the Doppel TI Configuration form.
    // Tests the values typed on the form; secrets left blank fall back to the stored ones.
    testConnectionWithValues: function () {
        if (!gs.hasRole('x_doppe_doppel_t_0.admin')) {
            return JSON.stringify({ success: false, stage: 'access',
                message: 'You need the Doppel admin role (x_doppe_doppel_t_0.admin) to test the connection.' });
        }
        var o = {
            version: this.getParameter('sysparm_api_version') == 'v2' ? 'v2' : 'v1',
            orgCode: String(this.getParameter('sysparm_org_code') || '').trim(),
            clientId: String(this.getParameter('sysparm_client_id') || '').trim()
        };
        var secrets = { apiKey: 'sysparm_api_key', userKey: 'sysparm_user_api_key', clientSecret: 'sysparm_client_secret' };
        for (var k in secrets) {
            var v = this.getParameter(secrets[k]);
            if (v) o[k] = String(v);
        }
        var result = new DoppelIOCImport().withConfig(o).testConnection();
        result.tested_at = new GlideDateTime().getDisplayValue();
        return JSON.stringify(result);
    },

    type: 'DoppelUIHelper'
});
